1282	\begin{lemma}[Formalization support for restricting a sum to one register]\label{lem:cl-restriction-sum}
1283		\lean{MIPStarRE.QPBT.coordinateRestriction_sum_eq}
1284		\leanok
1285		\uses{def:register-subspace}
1286		This is not a named statement of the source article; it isolates a step used in the Lean proofs of Lemma~\ref{lem:cl-func-prod} and Lemma~\ref{lem:cl-dist-prod}. Let $V^{(1)}, \dots, V^{(m)}$ be pairwise disjoint register subspaces of $V$ and, for each $j$, let $f_j \in V$ vanish outside $V^{(j)}$. Then $\bigl( \sum_{i=1}^m f_i \bigr)^{V^{(j)}} = f_j$ for every $j$.
1287	\end{lemma}
1288	\begin{proof}
1289		\leanok
1290		On a coordinate of $V^{(j)}$ every summand $f_i$ with $i \neq j$ vanishes, by disjointness, so the sum agrees there with $f_j$; outside $V^{(j)}$ both sides vanish.
1291	\end{proof}
